-- SF6 Tekken Mode PROBE: checks every row of sheets/hooks.json against the running game.
-- GENERATED by tools/build.py. Do not edit; change the sheets or src/probe.lua.tpl.
-- Use: start an offline match, open the REFramework menu (Insert), find "SF6 Tekken Probe", press the button.
-- It writes reframework/data/sf6_tekken/probe_report.json. Send that file back so the hook sheet can be marked verified.

local HOOKS = {
  {
    ["id"] = "round_no",
    ["kind"] = "field",
    ["path_steps"] = {
      "Round",
      "RoundNo"
    },
    ["access"] = "r",
    ["value_type"] = "int",
    ["purpose"] = "Detect a new round so per-round state resets",
    ["source"] = "SF6_replay_capture: gBattle.Round.RoundNo",
    ["verified"] = false
  },
  {
    ["id"] = "stage_timer",
    ["kind"] = "field",
    ["path_steps"] = {
      "Game",
      "stage_timer"
    },
    ["access"] = "r",
    ["value_type"] = "int",
    ["purpose"] = "Detect that the match simulation advanced one tick (render frames and sim ticks differ)",
    ["source"] = "SF6_replay_capture: gBattle.Game.stage_timer",
    ["verified"] = false
  },
  {
    ["id"] = "hp_now",
    ["kind"] = "field",
    ["path_steps"] = {
      "Player",
      "mcPlayer",
      "[i]",
      "vital_new"
    },
    ["access"] = "rw",
    ["value_type"] = "int",
    ["purpose"] = "Read health to find damage taken and Rage threshold; write it to add bonus damage and chip damage",
    ["source"] = "SF6_replay_capture: cPlayer[i].vital_new (read only there; writing is unproven)",
    ["verified"] = false
  },
  {
    ["id"] = "guard_time",
    ["kind"] = "field",
    ["path_steps"] = {
      "Player",
