  },
  {
    ["id"] = "juggle_counter",
    ["kind"] = "field",
    ["path_steps"] = {
      "Player",
      "mcPlayer",
      "[i]",
      "combo_dm_air"
    },
    ["access"] = "r",
    ["value_type"] = "int",
    ["purpose"] = "Research only: what SF6 tracks during air combos, to see whether juggle scaling can be changed",
    ["source"] = "SF6_replay_capture: cPlayer[i].combo_dm_air (meaning not confirmed)",
